        "id": 1790361153279,
        "variable": 0,
        "operator": "<=",
        "amount": 268,
        "endingTitle": "America's Bernt Out...",
        "endingSubtitle": "",
        "endingText": "<p>You and your campaign team watch the results Trickle in. The first states of the night don't exactly tell you much, given Kentucky was never really in play, although Vermont is slightly less blue than expected. Then, as more and more polls close in pivotal swing states, it's clear that the polling data released after the 'Access Hollywood' scandal was off by a mile. States like Indiana, expected to be competitive, were called even earlier than they were 4 years ago, despite your stronger appeal to working-class voters. Would Trump really win? Would the movement you've fought for for your entire political career be halted by a fascistic billionaire sex pest? \n<p>The atmosphere in the room is tense as everyone watches anxiously, state after state being called. Then, the nail in the coffin arrived; CNN called Pennsylvania... for Donald J. Trump. It seems that the 1% have succeeded in getting their corporate puppet elected to the presidency.",
        "endingImage": "https://imgur.com/gcIRsXO.png",
        "endingHideImage": false,
        "endingSlidesJson": "[\n  {\n    \"variable\": 0,\n    \"operator\": \"<=\",\n    \"amount\": 268,\n    \"outcomeCondition\": \"ignore\",\n    \"title\": \"America's Bernt Out...\",\n    \"subtitle\": \"\",\n    \"content\": \"<p>You and your campaign team watch the results Trickle in. The first states of the night don't exactly tell you much, given Kentucky was never really in play, although Vermont is slightly less blue than expected. Then, as more and more polls close in pivotal swing states, it's clear that the polling data released after the 'Access Hollywood' scandal was off by a mile. States like Indiana, expected to be competitive, were called even earlier than they were 4 years ago, despite your stronger appeal to working-class voters. Would Trump really win? Would the movement you've fought for for your entire political career be halted by a fascistic billionaire sex pest? \\n<p>The atmosphere in the room is tense as everyone watches anxiously, state after state being called. Then, the nail in the coffin arrived; CNN called Pennsylvania... for Donald J. Trump. It seems that the 1% have succeeded in getting their corporate puppet elected to the presidency.\",\n    \"image\": \"https://imgur.com/gcIRsXO.png\",\n    \"slideGroup\": \"main\",\n    \"variableConditions\": [],\n    \"variableConditionOperator\": \"AND\",\n    \"answerConditionType\": \"ignore\",\n    \"answerConditionAnswer\": \"\",\n    \"answerConditionAnswers\": \"\",\n    \"audio\": {\n      \"title\": \"All Time Low\",\n      \"artist\": \"Jon Bellion\",\n      \"cover\": \"https://cdn.imgchest.com/files/fb41c338799c.jpe\",\n      \"url\": \"https://audio.jukehost.co.uk/01a0e342-1d73-7215-b646-599c61854ab2\"\n    }\n  },\n  {\n    \"variable\": 0,\n    \"operator\": \">\",\n    \"amount\": 0,\n    \"outcomeCondition\": \"ignore\",\n    \"title\": \"The Call.\",\n    \"subtitle\": \"\",\n    \"content\": \"<p> You pick up the phone and make a call to the Trump campaign. An intern answers the phone and passes it to the president-elect. You can hear the jubilance of the campaign team over in Trump HQ. It makes you sick.\\n<p>\\\"Hello Mr. Trump, I was just calling to-\\\"\\n<p>\\\"Please, call me Donald. Y'know, I always knew this'd happen, even when the mainstream media went after me for those phony false allegations.\\\"\\n<p>\\\"Yes, well I just wanted to wish you luck during your presidency, and implore you to always do what's best for the American people.\\\"\\n<p>Trump lets out a little chuckle. \\\"I've always liked that about you, Bernie. You don't stand by the elites, the globalists, and instead stand up for our wonderful, wonderful workers. You may be a radical commie, but you're sure as hell more real than Crooked Hillary!\\\" You hear laughter from the staffers surrounding Trump as you two talk.\\n<p>You two proceed to exchange pleasantries and hang up. It's a crushing feeling to be defeated, but even moreso to be defeated by the likes of Trump. You give a concession speech while imploring your followers to \\\"never stop the fight\\\" for economic justice and a peaceful world. In your mind, you ponder running again in 2020, but you brush it off. It's unlikely you'd win the primary again anyway.\",\n    \"image\": \"\",\n    \"slideGroup\": \"secondary\",\n    \"variableConditions\": [],\n    \"variableConditionOperator\": \"AND\",\n    \"answerConditionType\": \"ignore\",\n    \"answerConditionAnswer\": \"\",\n    \"answerConditionAnswers\": \"\"\n  }\n]",
        "audioTitle": "All Time Low",
        "audioArtist": "Jon Bellion",
        "audioCover": "https://cdn.imgchest.com/files/fb41c338799c.jpe",
        "audioUrl": "https://audio.jukehost.co.uk/01a0e342-1d73-7215-b646-599c61854ab2",
        "endingAccentColor": "#11299e",
        "endingBackgroundColor": "#ffffff",
